def esc(x): return html.escape(str(x),quote=True)
def page(c):
 inputs=''.join(f'<label for="{x["id"]}">{esc(x["label"])}<input id="{x["id"]}" type="number" min="{x["min"]}" max="{x["max"]}" step="{x["step"]}" value="{x["value"]}"></label>' for x in c['inputs'])
 brief=''.join(f'<li>{esc(x)}</li>' for x in c['brief']); changes=''.join(f'<li>{esc(x)}</li>' for x in c['change']); decisions=''.join('<tr>'+''.join(f'<td>{esc(v)}</td>' for v in row)+'</tr>' for row in c['decision'])
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(c['title'])} | Financial &amp; Risk Intelligence</title><link rel="stylesheet" href="../shared/app.css"></head><body><header><nav><a href="/">← Main research portfolio</a> <a href="../">Daily release</a> <a href="../shared/audit.html">Audit &amp; sources</a></nav></header><main><div class="eyebrow">14 November 2026 / {esc(c['domain'])}</div><h1>{esc(c['title'])}</h1><p class="lead">{esc(c['subtitle'])}</p><div class="ribbon">EMPIRICAL EVIDENCE · EXPLICIT LIMITATIONS · USER SCENARIOS</div><section><h2>Research Intelligence Brief</h2><ol>{brief}</ol></section><section><h2>The mechanism and the test</h2><p>{esc(c['mechanism'])}</p></section><section><h2>Evidence explorer</h2><label for="choice">Explore sample<select id="choice"></select></label><p id="evidence-note"></p><div id="chart" class="chart"></div><div id="chart2" class="chart"></div><details><summary>Inspect observations and source flags</summary><div id="table" class="tablewrap"></div></details><button id="csv">Export selected evidence · CSV</button></section><section id="playground"><div class="eyebrow">USER SCENARIO — NOT AN EMPIRICAL RESULT</div><h2>Interactive playground</h2><p id="lab-note"></p><div class="controls">{inputs}</div><div id="result" class="result" aria-live="polite"></div><div id="scenario-chart" class="chart"></div><button id="reset">Reset assumptions</button> <button id="export">Export scenario · JSON</button></section><section><h2>Decision Matrix</h2><div class="tablewrap"><table><thead><tr><th>Decision owner</th><th>Action</th><th>Required evidence</th><th>Boundary</th></tr></thead><tbody>{decisions}</tbody></table></div></section><section><h2>Methodology &amp; limitations</h2><p>{esc(c['method'])}</p><p class="warning">{esc(c['limits'])}</p><a href="methodology.html">Separate methodology page →</a></section><section><h2>What Would Change Our Mind</h2><ul>{changes}</ul></section><section><h2>Sources &amp; reproducibility</h2><p><a href="{esc(c['source'])}">Official source</a> · <a href="../shared/results.json">Research data</a> · <a href="../shared/analyze.py">Analysis code</a> · <a href="../shared/reproduce.py">Reproduction runner</a> · <a href="../shared/audit.html">Audit and original source downloads</a></p><p>Source record vintage and publication date are distinct. Historical data are not relabelled as observations from today.</p></section><script id="config" type="application/json">{json.dumps(c,ensure_ascii=False).replace('</','<\\/')}</script><script src="../shared/app.js"></script></main><footer>Independent research · Public-source evidence · 14 November 2026 · Scenarios are assumptions, not forecasts.</footer></body></html>'''
def methodology(c):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Methodology | {esc(c['title'])}</title><link rel="stylesheet" href="../shared/app.css"></head><body><header><nav><a href="./">← Dashboard</a> <a href="../shared/audit.html">Audit &amp; sources</a></nav></header><main><div class="eyebrow">Methodology / 14 November 2026</div><h1>{esc(c['title'])}</h1><section><h2>Research question</h2><p>{esc(c['subtitle'])}</p></section><section><h2>Data and calculation</h2><p>{esc(c['method'])}</p></section><section><h2>Identification boundary</h2><p class="warning">{esc(c['limits'])}</p></section><section><h2>Validation classification</h2><p>Where a forward test is shown, it is explicitly latest-vintage and uses only earlier rows at each origin. A snapshot or definitional analysis is not presented as forecast validation. User scenarios are deterministic assumption laboratories and are not empirical forecasts.</p></section><section><h2>Reproduce</h2><p><a href="../shared/analyze.py">Main calculation path</a> · <a href="../shared/audit_research.py">Independent audit path</a> · <a href="../shared/results.json">Machine-readable results</a></p></section></main><footer>Independent research · 14 November 2026</footer></body></html>'''
